import * as ReactDOM from "react-dom";
import {createRoot} from "react-dom/client";

// React 19 removed ReactDOM.render. createRoot must be called once per
// container, whereas the pages call render repeatedly through the model's
// reactCallback, so roots are cached per container. root.render is also
// asynchronous and takes no completion callback, and didUpdate(cb) relies on
// the callback running after the DOM is updated, so flushSync restores the
// synchronous ordering the pages were written against.
const roots = new WeakMap();

function render(element, container, callback) {
  let root = roots.get(container);
  if (!root) {
    root = createRoot(container);
    roots.set(container, root);
  }
  ReactDOM.flushSync(() => root.render(element));
  if (callback) {
    callback();
  }
  // React 15 returned the component instance here; nothing in this codebase
  // uses it, and React 19 has no equivalent.
  return null;
}

window.ReactDOM = Object.assign({}, ReactDOM, {createRoot, render});
